		}
	}

	// If no pupils, each adult alone
	if pupils == 0 {
		fmt.Println(adults * c1)
		return
	}

	// Binary search on group size x
	low, high := int64(1), int64(n)
	var best int64 = -1

	for low <= high {
		mid := (low + high) / 2
		if feasible(mid, adults, pupils) {
			best = mid
			high = mid - 1
		} else {
			low = mid + 1
		}
	}

	// Compute minimal cost with group size best
	x := best
	groups := (adults + pupils + x - 1) / x
	costPerGroup := c1 + c2*(x-1)*(x-1)
	totalCost := groups * costPerGroup
	fmt.Println(totalCost)
}

func feasible(x, adults, pupils int64) bool {
	// Number of groups needed by capacity
	total := adults + pupils
	groups := (total + x - 1) / x

	// Each group must have at least one adult
	if groups > adults {
		return false
	}

	// Check if pupils can be distributed
	// Each group can have at most x-1 pupils (since at least one adult)
	maxPupils := groups * (x - 1)
	return pupils <= maxPupils
}

