func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	var c1, c2 int64
	if _, err := fmt.Fscan(in, &n, &c1, &c2); err != nil {
		return
	}
	var s string
	fmt.Fscan(in, &s)

	// Count adults and pupils
	var adults, pupils int64
	for i := 0; i < n; i++ {
		if s[i] == '1' {
			adults++
		} else {
			pupils++
		}
	}

	// If no pupils, only adults: optimal is one group of all adults
	if pupils == 0 {
		x := adults
		ans := c1 + c2*(x-1)*(x-1)
		fmt.Println(ans)
		return
	}

	// We must have at least one adult per group, so number of groups k
	// satisfies 1 <= k <= adults and k <= adults (since each group needs adult)
	// Total people n = adults + pupils, each group size >=1, so k <= n.
	// We'll iterate k over 1..adults and compute minimal cost.

	minCost := int64(1<<62 - 1)

	// Precompute prefix sums of squares to help distribute sizes?
	// Actually, we can reason: we have n people, k groups, each size >=1.
	// Sum x_i = n, minimize sum (c1 + c2*(x_i-1)^2).
	// c1*k is fixed for given k, so minimize sum (x_i-1)^2 with sum x_i fixed.
	// This is minimized when sizes are as equal as possible.
	// Let base = n / k, rem = n % k.
	// Then rem groups have size base+1, others base.
	// But each group must have at least one adult. This may not be feasible
	// if base is large and adults insufficient to distribute.
	// However, since adults >= k, we can always assign at least one adult per group,
	// and remaining people (adults+pupils) can be distributed arbitrarily.
	// So equal distribution is feasible.

	totalPeople := adults + pupils

	for k := int64(1); k <= adults; k++ {
		base := totalPeople / k
		rem := totalPeople % k

		// group sizes: rem groups of size base+1, (k-rem) groups of size base
		// cost = k*c1 + c2 * [ rem*(base)^2 + (k-rem)*(base-1)^2 ]
		// because (x-1)^2: for size base+1 -> (base)^2, for size base -> (base-1)^2
		var sumSquares int64
		if base > 0 {
			bm1 := base - 1
			sumSquares = rem*base*base + (k-rem)*bm1*bm1
		} else {
			// base == 0 cannot happen since totalPeople >= k (each group at least 1)
			continue
		}
		cost := k*c1 + c2*sumSquares
		if cost < minCost {
			minCost = cost
		}
	}

	fmt.Println(minCost)
}
