	// but pupils can be arbitrarily distributed among groups.
	// The cost of a group of size x is: c1 + c2 * (x-1)^2.
	// Since cost is convex in x, optimal strategy is:
	// - Decide number of groups g (1 <= g <= adults), each group must have at least 1 adult.
	// - Distribute adults and pupils among g groups as evenly as possible.
	// Total people = n, so group sizes are either floor(n/g) or ceil(n/g).
	// Let q = n / g, r = n % g. Then r groups have size q+1, others size q.
	// Total cost = r * (c1 + c2*(q)^2) + (g-r) * (c1 + c2*(q-1)^2).
	// We must ensure g <= adults (since each group needs an adult).
	// We brute over g from 1 to adults (adults <= n <= 2e5), which is feasible.

	total := int64(n)
	var best int64 = -1

	for g := int64(1); g <= adults; g++ {
		q := total / g
		r := total % g

		// group sizes: r groups of size q+1, g-r groups of size q
		// cost per group size x: c1 + c2*(x-1)^2
		// for size q+1: x-1 = q
		// for size q:   x-1 = q-1

