	for i := 0; i < n; i++ {
		if s[i] == '1' {
			adults++
		} else {
			pupils++
		}
	}

	// If there are no pupils, each adult can go alone
	if pupils == 0 {
		fmt.Println(adults * c1)
		return
	}

	// We need at least one adult per group, and every pupil must be in some group.
	// Let g be the number of groups.
	// Constraints:
	//   1 <= g <= adults
	//   g <= adults + pupils (trivial)
	//   Each group has at least 1 adult, so adults >= g.
	//   Each group has at least 1 person, so total n >= g.
	//
	// We want to partition n people into g groups with sizes x_i >= 1, sum x_i = n,
	// and each group has at least one adult. The cost is:
	//   sum (c1 + c2 * (x_i - 1)^2) = g*c1 + c2 * sum (x_i - 1)^2
	// For fixed g, cost is minimized when sizes are as equal as possible.
	//
	// Let base = n / g, rem = n % g.
	// Then we can have rem groups of size base+1 and g-rem groups of size base.
	// But we must ensure we can assign adults so that each group has at least one adult.
	//
	// The minimal number of adults needed is g (one per group).
	// Remaining adults and pupils are just "extra" people to fill groups.
	// Since we don't distinguish adults/pupils in cost, and we only need at least one adult per group,
	// it's always possible if adults >= g (we can assign one adult per group first, then distribute others).
	//
	// So for each feasible g (1..adults), compute minimal cost with equalized sizes and take minimum.

	n64 := int64(n)
	var best int64 = -1

	for g := int64(1); g <= adults; g++ {
		base := n64 / g
		rem := n64 % g

		// sum (x_i - 1)^2:
		// rem groups of size base+1 => (base)^2
		// g-rem groups of size base   => (base-1)^2
		// because (x_i - 1) for size base+1 is base, for size base is base-1
		b1 := base - 1
		sumSq := rem*base*base + (g-rem)*b1*b1

		cost := g*c1 + c2*sumSq
		if best == -1 || cost < best {
			best = cost
		}
	}

	fmt.Println(best)
